    const colWidths = [6, 10, 20, 18, 18, 26, 34, 26, 26, 14, 24, 16, 26, 20, 14, 14, 14, 20, 20, 20, 22];
    downloadRealXlsxFile(filePrefix, 'Data Aset PNS', aoa, colWidths);
